if "banco_ok" not in st.session_state:
    try:
        inicializar_banco()
        import database as _db_diag
        st.session_state.banco_ok    = True
        st.session_state.usando_pg   = _db_diag._usar_postgres()
    except Exception as _e_init:
        st.error(f"Erro ao inicializar banco: {_e_init}")
        st.stop()

if not st.session_state.get("usando_pg", False):
    st.sidebar.error("SQLite local - dados nao persistem!")

# ── helper ──────────────────────────────────────────────────────────────────
def hdr(icone, titulo, sub=""):
    st.markdown(f"## {icone} {titulo}")
    if sub: st.caption(sub)
    st.divider()

@st.cache_data(ttl=600, show_spinner=False)
def _listar_lotes_cache(owner_id=None):
    return listar_lotes(owner_id=owner_id)

@st.cache_data(ttl=600, show_spinner=False)
def _listar_animais_cache(lote_id):
    return listar_animais_por_lote(lote_id)

def _limpar_cache():
    _listar_lotes_cache.clear()
    _listar_animais_cache.clear()

def _is_admin():
    u = st.session_state.get("usuario")
    return bool(u and u.get("perfil") == "admin")

def _is_vet():
    u = st.session_state.get("usuario")
    return bool(u and u.get("perfil") == "veterinario")

def _owner_id():
    u = st.session_state.get("usuario")
    if not u: return None
    if u.get("perfil") == "admin": return None
    return u.get("owner_id", u["id"])

def _owner_id_medicamentos():
    u = st.session_state.get("usuario")
    if not u: return None
    if _is_admin(): return None
    if _is_vet():
        fazendas = listar_fazendas_do_vet(u["id"])
        return fazendas[0] if fazendas else None
    return u.get("owner_id", u["id"])

def _listar_medicamentos_usuario():
    if _is_admin():
        return listar_medicamentos(owner_id=None)
    if _is_vet():
        fazendas = listar_fazendas_do_vet(st.session_state.get("usuario",{}).get("id"))
        if not fazendas: return []
        todos = []
        for fid in fazendas:
            todos.extend(listar_medicamentos(owner_id=fid))
        return todos
    return listar_medicamentos(owner_id=_owner_id())

def _listar_lotes_usuario():
    u = st.session_state.get("usuario")
    if not u: return []
    if _is_admin(): return listar_lotes()
    if _is_vet():   return listar_lotes_vet(u["id"])
    return _listar_lotes_cache(owner_id=_owner_id())

def sel_lote(key="lote"):
    lotes = _listar_lotes_usuario()
    if not lotes:
        st.warning("Nenhum lote cadastrado. Va em Cadastrar Lote primeiro.")
        return None, None
    d = {f"{l[1]} (ID {l[0]})": l[0] for l in lotes}
    sel = st.selectbox("Lote", list(d.keys()), key=key)
    return d[sel], lotes

def sel_animal(lote_id, key="animal"):
    animais = _listar_animais_cache(lote_id)
    if not animais:
        st.warning("Nenhum animal neste lote.")
        return None
    d = {f"{a[1]} (ID {a[0]})": a[0] for a in animais}
    sel = st.selectbox("Animal", list(d.keys()), key=key)
    return d[sel]

# ── autenticacao ─────────────────────────────────────────────────────────────
if "usuario" not in st.session_state:
    st.session_state.usuario = None

if st.session_state.usuario is None:
    st.title("Gestao Pecuaria")
    if not usuario_existe():
        st.info("Primeiro acesso: crie sua conta de administrador.")
        with st.form("form_first"):
            nome  = st.text_input("Nome")
            email = st.text_input("E-mail")
            senha = st.text_input("Senha", type="password")
            perf  = st.selectbox("Perfil", ["admin","veterinario","fazendeiro"])
            if st.form_submit_button("Criar conta"):
                if nome and email and senha:
                    uid = criar_usuario(nome, email, senha, perf)
                    ativar_trial(uid)
                    email_boas_vindas(email, nome)
                    st.success("Conta criada! Faca login.")
                    st.rerun()
                else:
                    st.error("Preencha todos os campos.")
    else:
        with st.form("form_login"):
            email = st.text_input("E-mail")
            senha = st.text_input("Senha", type="password")
            if st.form_submit_button("Entrar"):
                u = autenticar_usuario(email, senha)
                if u:
                    # Garantir owner_id no session (None = admin ve tudo)
                    if u.get("perfil") == "admin":
                        u["owner_id"] = None
                    elif not u.get("owner_id"):
                        u["owner_id"] = u["id"]
                    st.session_state.usuario = u
                    st.rerun()
                else:
                    st.error("E-mail ou senha incorretos.")
    st.stop()

