                with u2:
                    animais_u = listar_animais_por_lote(dict_l[lote_s])
                    dict_au   = {f"{a[1]} (ID {a[0]})": a[0] for a in animais_u}
                    anim_s    = st.selectbox("Animal", list(dict_au.keys()) if dict_au else ["--"])
